import{_ as p,c as e,a2 as t,o as r}from"./chunks/framework.CqbvlPrP.js";const _=JSON.parse('{"title":"如果期货是赌博，那么我就是赌场","description":"","frontmatter":{},"headers":[],"relativePath":"stock/游戏类比/如果期货是赌博，那么我就是赌场.md","filePath":"stock/游戏类比/如果期货是赌博，那么我就是赌场.md"}'),o={name:"stock/游戏类比/如果期货是赌博，那么我就是赌场.md"};function i(h,a,l,n,s,d){return r(),e("div",null,a[0]||(a[0]=[t('<h1 id="如果期货是赌博-那么我就是赌场" tabindex="-1">如果期货是赌博，那么我就是赌场 <a class="header-anchor" href="#如果期货是赌博-那么我就是赌场" aria-label="Permalink to &quot;如果期货是赌博，那么我就是赌场&quot;">​</a></h1><p>天启大烁哥</p><p>“一套完整的交易系统，它的作用是什么？它为什么具有优势？”</p><p>以前我回答这个问题，喜欢列举各种各样的系统，比如，可口可乐的系统，麦当劳的系统等等。交易系统本身的模式很容易解释，但是在解释它为什么会具有优势的时候，总是觉得这些例子有点费时费力，而且解释的并不清楚。</p><p>现在我发现，最好的例子，其实是赌场。赌场的运作模式，赌场的优势来源都可以完美的解释这个问题。</p><h2 id="把自己当赌场" tabindex="-1">把自己当赌场 <a class="header-anchor" href="#把自己当赌场" aria-label="Permalink to &quot;把自己当赌场&quot;">​</a></h2><p>在很多人眼里，期货和赌博非常像。因为任何一笔交易单子进场，都是一个未知的命运，面对不确定性，要么止损，要么止盈，这就是有“赌”的成分在里面。从这个角度来看，这个说法也并没有错误。</p><p>期货交易是一个处理不确定的领域。我们来到这个领域，想要实现的终极目标只有一个：长期持续的获利。</p><p>然而我们都知道，久赌必输。</p><p>所以，如果我们纯粹的以赌博的思路去运作交易，真的把自己当成了赌徒的话，那么几乎都是死路一条。</p><p>做交易，我们不应该把自己当成赌徒，而是应该把自己当成赌场。</p><h2 id="赌场的交易系统" tabindex="-1">赌场的交易系统 <a class="header-anchor" href="#赌场的交易系统" aria-label="Permalink to &quot;赌场的交易系统&quot;">​</a></h2><p>所有的赌场追求的都是持续稳定的获利。为了达成这个目标，它们做了很多事情。</p><p>首先，它设立了规则。每一种赌场游戏都有它自己的规则，有的规则多，有的规则少。这些规则组合到了一起，让它拥有了核心的概率的优势。</p><p>比如，赌场中的轮盘游戏。</p><p>在这个游戏中，一个圆盘中共有37个小格。游戏开始后，轮盘转动，然后出来一颗珠子，珠子最后落在那一个格的数字就是得奖号码。</p><p>这其中的概率我们其实很容易算出来。如果说我们单次下注的赔率能够达到1赔36的话，那么对于赌客而言，这个游戏其实非常公平。</p><p>但是在实际情况中呢？赌场给予的赔率是1:35。</p><p>这样的话，就让赌场在赔率上具有了优势,其优势就是36/37=2.7%。在轮盘游戏中的美式玩法中，由于规则有所不同，赌场的优势甚至可以达到5.26%。</p><p>其他游戏同样如此。再比如扑克牌中的21点，同样利用几个简单的规则，赌场的优势就比玩家多出来了4.5%。</p><p>不要小看这个利用游戏规则构建出的基于概率的小小优势。它就是赌场盈利的核心来源。</p><p>请注意，赌场并不是逢赌必赢，而是长赌必赢。这背后就是简单的大数定律：在随机事件的大量重复过程中，往往呈现几乎必然的规则。</p><p>比如，你抛几次硬币，其正反面的数量可能是随机的，无法预估的。但是你抛一万次硬币，最后统计的结果一定是无限接近50%。</p><p>赌场也是如此。它的概率优势需要长期的大量的重复行为才能够获取，因此，赌场接下来的工作，其实就是吸引人来参加游戏。</p><p>豪华的装修，免费的饮食，看不见的时钟…这一切都是想让赌客不要停下来。</p><p>在赌场中，赌场会见过无数个赌徒在他的赌场中盈盈亏亏，而且在任何一个时期，他的赌场里都有会那么几个人，在那里疯狂的获利。这是概率分布的必然结果，每时每刻总有那么几个被运气笼罩的人，他在意吗？他并不在意。他在意的是他整体的逻辑是否具有优势而已。</p><p>只要优势在，次数足够多之后，他的概率优势一定会让他获取收益。</p><p>这就是赌场获利的根源所在，它多个规则组合到一起，形成了一个简单粗暴且高效的正收益逻辑。</p><h2 id="投机交易系统" tabindex="-1">投机交易系统 <a class="header-anchor" href="#投机交易系统" aria-label="Permalink to &quot;投机交易系统&quot;">​</a></h2><p>投机交易也同样如此。</p><h3 id="_1、交易逻辑" tabindex="-1">1、交易逻辑 <a class="header-anchor" href="#_1、交易逻辑" aria-label="Permalink to &quot;1、交易逻辑&quot;">​</a></h3><p>基于赌场思维，面对走势的不确定性，单次交易的结果是无法预知的。因此，我们不能把自己当成一个赌场，想要逢赌必赢，而是应该把自己当成是一个赌场。我们应该关注的，是自己背后的那个交易逻辑是否具有长期的优势。</p><p>长期优势来源何处？决定交易盈亏的最终结果的，永远是胜率*盈亏比。长期的优势，要么来源于胜率，要么来源于盈亏比。</p><p>在上述的例子轮盘游戏中，赌场属于在盈亏比上具有了优势。其在胜率固定的基础上，利用规则将盈亏比提高了。</p><p>想要在交易中具有如此优势，很明显，我已经谈过无数次：截断亏损让利润奔跑即可。</p><h3 id="_2、交易周期与级别" tabindex="-1">2、交易周期与级别 <a class="header-anchor" href="#_2、交易周期与级别" aria-label="Permalink to &quot;2、交易周期与级别&quot;">​</a></h3><p>同样，我们要知道，想要将这个优势发挥出来，需要大数定律发挥作用。而想要发挥出大数定律的作用，你需要足够多的交易次数和时间。</p><p>假如有人的系统胜率40%，盈亏2比1。这是不是一套很好的系统？但是，其一年的时间内可能交易次数有限。这样的话，他的盈利周期就需要放大，因为概率优势的发挥需要次数。很多人天天急不可耐的想要自己的系统天天新高，这属于没有从足够高的视角来看待自己的系统。</p><p>为什么短周期小级别的交易策略往往表现的更加优秀，曲线更为平滑？从大数定律的角度也可以解释，短周期小级别的策略交易次数更多，概率优势体现的更快而已。</p><p>当然，这里并不是说越小周期的策略越好，因为我们期货交易者跟真正的成为一个赌场有一个无法逾越的鸿沟：交易手续费。交易手续费的持续输出限制了过小的级别。</p><p>因此，在交易周期和交易级别的选择上要综合权衡两种情况，合适就好。</p><h3 id="_3、资金管理" tabindex="-1">3、资金管理 <a class="header-anchor" href="#_3、资金管理" aria-label="Permalink to &quot;3、资金管理&quot;">​</a></h3><p>同样，为了不在前期过早的损失惨重，分散化的思路必不可少，分散品种，分散资金。防止被极限的概率意外直接带走，这就是交易系统中的资金管理。</p><p>因此可以看到，赌场总是有很多游戏，赌场也会出某些赌注的限制政策，其目的，就是能够保证其核心的优势一直稳定的被输出，而不会被极限的意外所带走。</p><p>以上几点，就是交易系统和赌场思维的相似之处。</p><p>很多人羡慕那些在赌场上气运加身而产生的暴利的人，但是他们并不知道这是概率下的必然现象：幸存者偏差。很多人看着胜率和盈亏比具有优势的交易系统而无动于衷，因为他们无法接受那显而易见的回撤可能性，殊不知，赌场一点小小的优势就可以创造出惊人的收益。很多人一直追求单单正确，短期暴利，但是他们可能不明白，以赌场思维去运作交易，才是真正长期持续盈利的根源。</p><p>之所以如此，是因为他们根本就没有切换过来视角，一直都是一个单纯的赌徒而已。</p>',47)]))}const u=p(o,[["render",i]]);export{_ as __pageData,u as default};
